styles:
.destination-card {
  --destination-card-radius: 10px;
  --destination-card-accent: #087ac4;
  position: relative;
  width: 300px;
  height: 400px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: flex-start;
  border-radius: var(--destination-card-radius);
  overflow: hidden;
  box-shadow: 0 15px 50px rgba(0, 0, 0, 0.2);
}

.destination-card .destination-card__media {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: 0;
}

.destination-card .destination-card__overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(15, 32, 39, 0.95), rgba(32, 58, 67, 0.35) 55%, rgba(44, 83, 100, 0));
  z-index: 1;
}

.destination-card .destination-card__badge {
  position: relative;
  z-index: 2;
  margin-top: 25px;
  text-transform: uppercase;
  color: #fff;
  background: var(--destination-card-accent);
  padding: 7px 18px 7px 25px;
  display: inline-block;
  border-radius: 0 20px 20px 0;
  letter-spacing: 2px;
  font-size: 0.8rem;
  font-weight: 500;
}

.destination-card .destination-card__body {
  position: relative;
  z-index: 2;
  padding: 25px;
}

.destination-card .destination-card__title {
  margin: 0 0 15px;
  color: #fff;
  font-weight: 400;
  font-size: 1.3rem;
  line-height: 1.4;
}

.destination-card .destination-card__location {
  margin: 0;
  display: flex;
  align-items: center;
  color: #fff;
  font-weight: 300;
}

.destination-card .destination-card__icon {
  width: 22px;
  height: 22px;
  margin-right: 7px;
  flex-shrink: 0;
}

.destination-card:hover {
  transform: translateY(-4px);
}

@media (max-width: 480px) {
  .destination-card {
    width: 100%;
    height: 340px;
  }
}
